import { readFileSync } from "node:fs";
import path from "node:path";

export type RedirectRule = { source: string; destination: string; permanent: boolean };

/**
 * Permanent redirects from the old site's URLs, maintained in
 * data/redirects.json (generated by scripts/migration/build-redirects.ts and
 * reviewed by hand). Entries whose source equals the destination are skipped.
 */
export function loadRedirects(file = path.join(process.cwd(), "data", "redirects.json")): RedirectRule[] {
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(file, "utf8"));
  } catch {
    return [];
  }
  if (!Array.isArray(raw)) return [];
  return raw
    .filter(
      (r): r is { source: string; destination: string; permanent?: boolean } =>
        !!r && typeof r.source === "string" && typeof r.destination === "string" && r.source.startsWith("/") && r.source !== r.destination,
    )
    .map((r) => ({ source: r.source, destination: r.destination, permanent: r.permanent !== false }));
}
